// Redirect hebleo.com based on login status
add_action( 'template_redirect', function () {

    // Don't do anything in the admin area
    if ( is_admin() ) {
        return;
    }

    // Only act on the main front page (the dummy homepage at hebleo.com)
    if ( ! is_front_page() ) {
        return;
    }

    // If the user is logged in, send them to the BuddyBoss dashboard
    if ( is_user_logged_in() ) {
        // TODO: change /dashboard/ to your actual BuddyBoss dashboard path
        wp_safe_redirect( site_url( '/my-dashboard/' ) );
        exit;
    }

    // If the user is NOT logged in, send them to the public welcome page
    wp_safe_redirect( site_url( '/welcome/' ) );
    exit;
} );

add_action('template_redirect', function () {
    // Redirect the old /dashboard page to /my-dashboard
    if (is_page('dashboard')) { // you can also use the page ID here
        wp_redirect( home_url('/my-dashboard/'), 301 );
        exit;
    }
});
